def parse_duration(s: str) -> int:
    total = 0
    for part in s.split():
        num = int(part[:-1])
        unit = part[-1]
        if unit == 'h':
            total += num * 3600
        elif unit == 'm':
            total += num * 60
        elif unit == 's':
            total += num
    return total
```

